    """
    A recursive descent parser that processes a JSON string to convert it into 
    corresponding Python objects. It handles strings (with escape sequences), 
    numbers, booleans, null, arrays, and objects.
    """
    def parse_value(index):
        if s[index] == '"':
            return parse_string(index)
        elif s[index] in '-0123456789':
            return parse_number(index)
        elif s[index:index + 4] == 'true':
            return True, index + 4
        elif s[index:index + 5] == 'false':
            return False, index + 5
        elif s[index:index + 4] == 'null':
            return None, index + 4
        elif s[index] == '[':
            return parse_array(index)
        elif s[index] == '{':
            return parse_object(index)
        raise ValueError("Invalid JSON at index {}".format(index))

    def parse_string(index):
        index += 1
        result = []
        escape = False
        while index < len(s):
            char = s[index]
            if escape:
                if char in '"\\/bfnrt':
                    result.append({
                        '"': '"', '\\': '\\', '/': '/', 
                        'b': '\b', 'f': '\f', 'n': '\n', 
                        'r': '\r', 't': '\t'
                    }[char])
                else:
                    raise ValueError("Invalid escape at index {}".format(index))
                escape = False
            elif char == '\\':
                escape = True
            elif char == '"':
                return ''.join(result), index + 1
            else:
                result.append(char)
            index += 1
        raise ValueError("Unterminated string starting at index {}".format(index))

    def parse_number(index):
        start = index
        if s[index] == '-':
            index += 1
        if s[index] == '0':
            index += 1
        else:
