            if index < len(s) and (s[index] == '+' or s[index] == '-'):
                index += 1
            while index < len(s) and s[index].isdigit():
                index += 1
        return float(s[start:index]), index

    def parse_array(index):
        index += 1
        result = []
        while index < len(s):
            if s[index] == ']':
                return result, index + 1
            value, index = parse_value(index)
            result.append(value)
            if s[index] == ',':
                index += 1
            elif s[index] == ']':
                return result, index + 1
            else:
                raise ValueError("Invalid character in array at index {}".format(index))
        raise ValueError("Unterminated array starting at index {}".format(index))

    def parse_object(index):
        index += 1
        result = {}
        while index < len(s):
            if s[index] == '}':
                return result, index + 1
            key, index = parse_string(index)
