                return result, index + 1
            else:
                raise ValueError("Invalid character in object at index {}".format(index))
        raise ValueError("Unterminated object starting at index {}".format(index))

    result, index = parse_value(0)
    if index != len(s):
        raise ValueError("Extra data after JSON at index {}".format(index))
    return result

def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a state-machine approach.
    It handles strings (with escapes), numbers, booleans, null, arrays, and objects.
    """

    class ParseError(Exception):
        pass

    index = 0
    length = len(s)

    def skip_whitespace():
        nonlocal index
        while index < length and s[index].isspace():
            index += 1

    def parse_value():
        skip_whitespace()
        if index >= length:
            raise ParseError("Unexpected end of input")

        char = s[index]

        if char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        elif char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            return parse_number()
        elif s.startswith('true', index):
            index += 4
            return True
        elif s.startswith('false', index):
            index += 5
            return False
        elif s.startswith('null', index):
            index += 4
            return None
        else:
            raise ParseError(f"Unexpected character: {char}")

    def parse_object():
        obj = {}
        index += 1  # Skip '{'
        skip_whitespace()
        if s[index] == '}':
            index += 1  # Empty object
            return obj

        while True:
            key = parse_string()
            skip_whitespace()
            if s[index] != ':':
                raise ParseError("Expected ':'")
            index += 1  # Skip ':'
            value = parse_value()
            obj[key] = value

            skip_whitespace()
            if s[index] == '}':
                index += 1  # Skip '}'
                break
            elif s[index] != ',':
                raise ParseError("Expected ',' or '}'")
            index += 1  # Skip ','

        return obj

    def parse_array():
        arr = []
        index += 1  # Skip '['
        skip_whitespace()
        if s[index] == ']':
            index += 1  # Empty array
            return arr

        while True:
            value = parse_value()
            arr.append(value)
            skip_whitespace()
            if s[index] == ']':
                index += 1  # Skip ']'
                break
            elif s[index] != ',':
                raise ParseError("Expected ',' or ']'")
            index += 1  # Skip ','

        return arr

    def parse_string():
        nonlocal index
        index += 1  # Skip opening '"'
        start = index
        result = ""

        while index < length:
            char = s[index]
            if char == '"':
                result += s[start:index]
                index += 1  # Skip closing '"'
                return result
            elif char == '\\':
                result += s[start:index]
                index += 1  # Skip backslash
                if index >= length:
                    raise ParseError("Unexpected end of input in string")
                escape_char = s[index]
                if escape_char == 'n':
                    result += '\n'
                elif escape_char == 't':
                    result += '\t'
                elif escape_char in '"\\/':
                    result += escape_char
                elif escape_char == 'b':
                    result += '\b'
                elif escape_char == 'f':
                    result += '\f'
                elif escape_char == 'r':
                    result += '\r'
                else:
                    raise ParseError(f"Invalid escape character: {escape_char}")
                index += 1  # Skip escape character
                start = index
            else:
                index += 1

        raise ParseError("Unmatched double quotes in string")

    def parse_number():
        nonlocal index
        start = index
        if s[index] == '-':
            index += 1  # Skip '-'
        if index < length and s[index] == '0':
            index += 1  # Skip '0'
        else:
            while index < length and s[index].isdigit():
                index += 1
        if index < length and s[index] == '.':
            index += 1  # Skip '.'
            if index >= length or not s[index].isdigit():
                raise ParseError("Invalid number format")
            while index < length and s[index].isdigit():
                index += 1
        num_str = s[start:index]
        try:
            return int(num_str) if '.' not in num_str else float(num_str)
        except ValueError:
            raise ParseError("Invalid number")

    return parse_value()

