    """
    A simple recursive descent parser for JSON. The parser implements 
    methods for different JSON structures and handles strings, numbers, 
    booleans, null, arrays, and objects.
    """
    import re

    def parse_value(index):
        if s[index] == '"':
            return parse_string(index)
        elif s[index] == '{':
            return parse_object(index)
        elif s[index] == '[':
            return parse_array(index)
        elif s[index] == 't':
            return True, index + 4  # 'true' length
        elif s[index] == 'f':
            return False, index + 5  # 'false' length
        elif s[index] == 'n':
            return None, index + 4  # 'null' length
        elif s[index] in '-0123456789':
            return parse_number(index)

        raise ValueError(f"Unexpected character: {s[index]}")

    def parse_string(index):
        end_index = index + 1
        while end_index < len(s):
            if s[end_index] == '"':
                return s[index + 1:end_index], end_index + 1
            elif s[end_index] == '\\':
                end_index += 2  # Skip escape character and next character
            else:
                end_index += 1
        raise ValueError("Unterminated string")

    def parse_number(index):
        num_regex = r'-?(0|[1-9]\d*)(\.\d+)?([eE][+-]?\d+)?'
        match = re.match(num_regex, s[index:])
        if not match:
            raise ValueError("Invalid number")
        number = match.group(0)
        return (float(number) if '.' in number or 'e' in number.lower() else int(number), index + len(number))

    def parse_array(index):
        arr = []
        index += 1  # Skip the opening '['
        while index < len(s):
            index = skip_whitespace(index)
            if s[index] == ']':
                return arr, index + 1
            value, index = parse_value(index)
            arr.append(value)
            index = skip_whitespace(index)
            if s[index] == ',':
                index += 1  # Skip comma
            elif s[index] == ']':
                return arr, index + 1
            else:
                raise ValueError("Invalid array syntax")
        raise ValueError("Unterminated array")

    def parse_object(index):
        obj = {}
        index += 1  # Skip the opening '{'
        while index < len(s):
            index = skip_whitespace(index)
            if s[index] == '}':
                return obj, index + 1
            key, index = parse_string(index)
            index = skip_whitespace(index)
            if s[index] != ':':
                raise ValueError("Expected ':' after key")
            index += 1  # Skip colon
            index = skip_whitespace(index)
            value, index = parse_value(index)
            obj[key] = value
            index = skip_whitespace(index)
            if s[index] == ',':
                index += 1  # Skip comma
            elif s[index] == '}':
                return obj, index + 1
            else:
                raise ValueError("Invalid object syntax")
        raise ValueError("Unterminated object")

    def skip_whitespace(index):
        while index < len(s) and s[index].isspace():
            index += 1
        return index

    index = skip_whitespace(0)
    value, index = parse_value(index)
    index = skip_whitespace(index)
    if index != len(s):
        raise ValueError("Extra data after JSON")
    return value

